//	    fb.creator_id AS b_creator_id
//	FROM channel_edges a
//	JOIN channel_edges b
//	  ON a.from_channel_id = b.to_channel_id
//	 AND a.to_channel_id = b.from_channel_id
//	 AND a.from_channel_id < a.to_channel_id
//	JOIN channels fa ON fa.id = a.from_channel_id
//	JOIN channels fb ON fb.id = a.to_channel_id
//	WHERE a.kind = 'outlink'
//	  AND b.kind = 'outlink'
//	  AND a.to_channel_id IS NOT NULL
func (q *Queries) ListMutualOutlinkPairs(ctx context.Context) ([]*ListMutualOutlinkPairsRow, error) {
	rows, err := q.db.Query(ctx, listMutualOutlinkPairs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*ListMutualOutlinkPairsRow
	for rows.Next() {
		var i ListMutualOutlinkPairsRow
		if err := rows.Scan(
			&i.AID,
			&i.BID,
			&i.AUploader,
			&i.ACreatorID,
			&i.BUploader,
			&i.BCreatorID,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

