const searchUnassignedChannels = `-- name: SearchUnassignedChannels :many
SELECT
    c.id,
    c.platform,
    c.identity_key,
    c.uploader,
    c.canonical_url,
    (SELECT COUNT(*) FROM videos v WHERE v.channel_row_id = c.id)::bigint AS video_count,
    similarity(c.uploader, $1)::float4 AS score
FROM channels c
WHERE c.creator_id IS NULL
  AND btrim($1::text) <> ''
  AND (
    c.uploader ILIKE '%' || $1 || '%'
    OR c.identity_key ILIKE '%' || $1 || '%'
    OR c.canonical_url ILIKE '%' || $1 || '%'
    OR c.platform ILIKE '%' || $1 || '%'
    OR similarity(c.uploader, $1) > 0.35
  )
ORDER BY
    similarity(c.uploader, $1) DESC,
    video_count DESC,
    c.uploader
LIMIT $2
`

type SearchUnassignedChannelsParams struct {
	Query     string `db:"query" json:"Query"`
	PageLimit int32  `db:"page_limit" json:"PageLimit"`
}

type SearchUnassignedChannelsRow struct {
	ID           pgtype.UUID `db:"id" json:"ID"`
	Platform     string      `db:"platform" json:"Platform"`
	IdentityKey  string      `db:"identity_key" json:"IdentityKey"`
	Uploader     string      `db:"uploader" json:"Uploader"`
	CanonicalURL string      `db:"canonical_url" json:"CanonicalUrl"`
	VideoCount   int64       `db:"video_count" json:"VideoCount"`
	Score        float32     `db:"score" json:"Score"`
}

// SearchUnassignedChannels ranks unlinked channels by name/url match.
// Empty query returns no rows — callers pass a creator name for suggestions.
//
//	SELECT
//	    c.id,
//	    c.platform,
//	    c.identity_key,
//	    c.uploader,
//	    c.canonical_url,
//	    (SELECT COUNT(*) FROM videos v WHERE v.channel_row_id = c.id)::bigint AS video_count,
//	    similarity(c.uploader, $1)::float4 AS score
//	FROM channels c
//	WHERE c.creator_id IS NULL
//	  AND btrim($1::text) <> ''
//	  AND (
//	    c.uploader ILIKE '%' || $1 || '%'
//	    OR c.identity_key ILIKE '%' || $1 || '%'
//	    OR c.canonical_url ILIKE '%' || $1 || '%'
//	    OR c.platform ILIKE '%' || $1 || '%'
//	    OR similarity(c.uploader, $1) > 0.35
//	  )
//	ORDER BY
//	    similarity(c.uploader, $1) DESC,
//	    video_count DESC,
//	    c.uploader
//	LIMIT $2
func (q *Queries) SearchUnassignedChannels(ctx context.Context, arg *SearchUnassignedChannelsParams) ([]*SearchUnassignedChannelsRow, error) {
	rows, err := q.db.Query(ctx, searchUnassignedChannels, arg.Query, arg.PageLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*SearchUnassignedChannelsRow
	for rows.Next() {
		var i SearchUnassignedChannelsRow
		if err := rows.Scan(
			&i.ID,
			&i.Platform,
			&i.IdentityKey,
			&i.Uploader,
			&i.CanonicalURL,
			&i.VideoCount,
			&i.Score,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

